{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    edges = []
    for u, v, d in distances:
        w = max(core_distance[u], core_distance[v], d)
        # canonicalize endpoints for tie-breaking
        a, b = (u, v) if u < v else (v, u)
        edges.append((w, a, b))

    # sort by weight, then endpoint strings
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    needed = len(nodes) - 1

    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == needed:
                break

    if len(mst_edges) != needed:
        raise ValueError('graph disconnected')

    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
